    export const SendFormToArrolamentoIdentRep = async (
        baseUrl: string,
        arrolamentoId: string,
        formData: {
            created_by: string;
            form: {
                family_index: number;
                identificacao_responsavel: {
                    responsavel: boolean;
                    nome_completo: string;
                    data_nascimento: string;
                    nome_social: string;
                };
            };
        }
    ): Promise<any> => {
        try {
            const path = `/survey-resource/v1/arrolamentos/${arrolamentoId}`;

            const headers = {
                "Content-Type": "application/json",
            };

            const response = await fetch(`${baseUrl}${path}`, {
                method: "PATCH",
                headers,
                body: JSON.stringify(formData),
            });

            if (!response.ok) {
                const errorText = await response.text();
                throw new Error(`Erro na requisição: ${response.status} - ${errorText}`);
            }

            const json = await response.json();
            return json;
        } catch (error) {
            console.error("Erro ao enviar formulário para arrolamento:", error);
            throw error;
        }
    };

